query:
select min(u.lo) as "lo?", max(u.hi) as "hi?" from (
                (select min(id + 0) as lo, max(id + 0) as hi from brc20_events where block_height = $1)
                union all
                (select min(id + 0) as lo, max(id + 0) as hi from brc20_light_events where block_height = $1)
            ) u;
